/* ===== ✨ Ô TRANG BỊ THÁNH KHÍ (world/131-thanh-khi-trang-bi.js) — Fix395 — nạp SAU world/130 (Nhà Tinh Luyện) và ui/97 (Ô Linh Căn) =====
 * Tab 🎒 Túi, cột ô BÊN TRÁI nhân vật (.tsm-l), dưới ô 🌟 Linh Căn: thêm ô ✨ THÁNH KHÍ. Bấm ô → bảng 4 Thánh Khí (Kiếm · Cung · Khiên · Trượng/Gậy phép).
 *   • Thánh Khí chế ở Nhà Tinh Luyện (Làng Tân Thủ 3 · Nhà Số 5, world/130) — mỗi lần dung hợp ra 1 trong 4 món, lưu trên máy chủ (bảng tk_user, cột k1..k4).
 *   • Mỗi NHÂN VẬT chỉ chọn 1 món để tinh luyện (không đổi): chọn = TIÊU HAO 1 món đang có trên máy chủ (RPC tk_use — chạy thanh_khi_v2.sql) → món đó thành CẤP 1.
 *   • 10 cấp, phí nâng tăng dần: cấp 1→2 tốn 💰 100 triệu, mỗi cấp sau cộng thêm 100 triệu (100tr × cấp hiện tại; CF.cost + CF.costStep). Có cấp 1 → hiện icon nhỏ ngay sau tên cảnh giới trên đầu nhân vật.
 *   • Mặc định mọi món (không tăng theo cấp): +10% sát thương · +10% giáp · +10% máu · +10% xuyên giáp.
 *   • Riêng: Kiếm +10% ST thần thông (+5%/cấp) · Cung +10% ST bạo kích (+5%/cấp) · Khiên +10% miễn thương, 1% bỏ qua 1 đòn mạnh của quái (+0,5%/cấp)
 *            · Trượng +10% ST kỹ năng (+5%/cấp).
 *   • Cấp 10: mở THẦN THÔNG THÁNH KHÍ riêng từng món (tự thi triển khi có địch trong tầm, có hồi chiêu): CF.sk.
 *   Lưu: PS[cur].tkq = {i: 0 Kiếm | 1 Cung | 2 Khiên | 3 Trượng, lv: 1..10}  (theo từng nhân vật).
 * Móc (không sửa core): twB (cộng %dmgp/hpp/ndr/sdmg/cdmg/dred) · ZC.pd (giáp) · step (thần thông + Khiên: theo dõi máu, đòn ≥2% máu tối đa mới tính là đòn mạnh, mọi bản đồ) · nameTag (icon) · ui() (ô).
 * Chỉnh số: TKQ.cfg (CF). API: TKQ.open() · TKQ.close() · TKQ.get() */
(function(){
'use strict';
if(window.TKQ||typeof PS==='undefined'||typeof ui!=='function'||typeof document==='undefined')return;
var CF={maxLv:10,cost:100000000,costStep:100000000,base:10,per:5,kiem:10,cung:10,khien:10,gay:10,ign:1,ignPer:.5,ignMin:.02,range:620,
  sk:[{n:'Thiên Quang Trảm',cd:480,d:'Mỗi 8 giây chém 5 địch gần nhất, mỗi nhát ×6 công.',m:6,n:5},
      {n:'Vạn Vũ Quang Tiễn',cd:540,d:'Mỗi 9 giây bắn 10 mũi tên ánh sáng vào địch ngẫu nhiên, mỗi mũi ×2,5 công.',m:2.5,n:10},
      {n:'Thánh Quang Hộ Thể',cd:1200,d:'Mỗi 20 giây hồi 20% máu và bất khả xâm phạm 3 giây.',heal:.2,inv:180},
      {n:'Quang Minh Thiên Giáng',cd:600,d:'Mỗi 10 giây giáng ánh sáng lên mọi địch trong tầm (×7 công) và hồi 10% năng lượng.',m:7,mp:.1}]};
var IC={"kiem": "data:image/webp;base64,", "gay": "data:image/webp;base64,", "cung": "data:image/webp;base64,", "khien": "data:image/webp;base64,"};
var IT=[{k:'kiem',n:'Thánh Kiếm',e:'⚔️',c:'#ffd27a',r:'ST thần thông'},
        {k:'cung',n:'Thánh Cung',e:'🏹',c:'#ffe27a',r:'ST bạo kích'},
        {k:'khien',n:'Thánh Khiên',e:'🛡️',c:'#ffcf6a',r:'Miễn thương'},
        {k:'gay',n:'Thánh Trượng (Gậy phép)',e:'🪄',c:'#ffd98a',r:'ST kỹ năng'}];
var IMG={};IT.forEach(function(it){var im=new Image();im.src=IC[it.k];IMG[it.k]=im});
/* đổi tên 4 món ở Nhà Tinh Luyện (world/130) cho khớp */
try{if(window.TKL_CF&&TKL_CF.items)IT.forEach(function(it,i){if(TKL_CF.items[i]){TKL_CF.items[i].n=it.n;TKL_CF.items[i].e=it.e;TKL_CF.items[i].c=it.c;TKL_CF.items[i].ic=IC[it.k]}})}catch(e){}

function nf(n){try{return Math.round(n).toLocaleString('vi-VN')}catch(e){return ''+n}}
function say(s,c){try{DT.push({x:P.x,y:210,s:s,c:c||'#ffd76a',l:110,g:1})}catch(e){}}
function sav(){try{if(typeof sv==='function')sv()}catch(e){}}
function G(){try{return typeof gold==='number'?gold:0}catch(e){return 0}}
var mR=null,mI=-9,mL=-9,mV=null;
/* có ghi nhớ theo (tham chiếu, i, lv) → không tạo đối tượng mới mỗi lần tính chỉ số */
function T(){try{var t=PS[cur].tkq;if(!t)return null;if(t===mR&&t.i===mI&&t.lv===mL)return mV;mR=t;mI=t.i;mL=t.lv;mV=(t.i>=0&&t.i<4)?{i:t.i|0,lv:Math.max(1,Math.min(CF.maxLv,t.lv|0))}:null;return mV}catch(e){return null}}
function isTT(){try{return !!(window.TTHONG&&TTHONG.on&&TTHONG.on())}catch(e){return false}}
function ex(lv){return CF.per*(lv-1)}
function ign(lv){return CF.ign+CF.ignPer*(lv-1)}

/* ---------- chỉ số ---------- */
function bonus(k){
  var t=T();if(!t)return 0;var v=0;
  if(k==='dmgp'||k==='hpp'||k==='ndr')v+=CF.base;
  if(t.i===0&&k==='sdmg'&&isTT())v+=CF.kiem+ex(t.lv);
  if(t.i===1&&k==='cdmg')v+=CF.cung+ex(t.lv);
  if(t.i===2&&k==='dred')v+=CF.khien;
  if(t.i===3&&k==='sdmg')v+=CF.gay+ex(t.lv);
  return v}
if(typeof twB==='function'){var _tw=twB;twB=function(k){var v=_tw.apply(this,arguments);try{v+=bonus(k)}catch(e){}return v}}
try{var _pd=ZC.pd;ZC.pd=function(){var v=_pd.apply(this,arguments);try{if(T())v*=1+CF.base/100}catch(e){}return v}}catch(e){}

/* ---------- Khiên: bỏ qua đòn mạnh + bất khả xâm phạm (theo dõi máu mỗi khung, mọi nguồn sát thương) ---------- */
var shU=0,hpP=-1;

/* ---------- thần thông thánh khí (cấp 10) ---------- */
var cdU={};
function foes(){var a=[];try{for(var i=0;i<E.length;i++){var e=E[i];if(e&&e.hp>0&&e.k!=='pal'&&!(e.in>0)&&Math.abs(e.x-P.x)<=CF.range)a.push(e)}}catch(x){}return a}
function hit(e,m){var f=typeof SKF!=='undefined';if(f)SKF=1;try{dm(e,m,0)}finally{if(f)SKF=0}}
function cast(i,tg){
  var s=CF.sk[i];say('✨ '+s.n,IT[i].c);
  if(i===0){tg.sort(function(a,b){return Math.abs(a.x-P.x)-Math.abs(b.x-P.x)});tg.slice(0,s.n).forEach(function(e){hit(e,s.m)})}
  else if(i===1){for(var j=0;j<s.n;j++)hit(tg[Math.floor(Math.random()*tg.length)],s.m)}
  else if(i===2){P.hp=Math.min(mx(),P.hp+mx()*s.heal);shU=fr+s.inv;hpP=P.hp}
  else{tg.slice(0,14).forEach(function(e){hit(e,s.m)});P.mp=Math.min(mm(),P.mp+mm()*s.mp)}}
function tick(){
  var t=T();if(!t||!started||over||vil){hpP=-1;return}
  var hp=P.hp;
  if(hpP>=0&&hp<hpP){
    if(shU>fr){hp=P.hp=hpP}
    else if(t.i===2&&hpP-hp>=mx()*CF.ignMin&&Math.random()*100<ign(t.lv)){hp=P.hp=hpP;say('🛡 Bỏ qua đòn!','#ffe27a')}}
  hpP=hp;
  if(t.lv<CF.maxLv||fr%10)return;
  var ck=cur*4+t.i;if(fr<(cdU[ck]|0))return;var tg=foes();if(!tg.length)return;
  cdU[ck]=fr+CF.sk[t.i].cd;cast(t.i,tg)}
if(typeof step==='function'){var _stp=step;step=function(){var r=_stp.apply(this,arguments);try{tick()}catch(e){}return r}}

/* ---------- icon nhỏ sau tên cảnh giới trên đầu ---------- */
var wcK='',wcA=0,wcB=0;
if(typeof nameTag==='function'){var _nt=nameTag;nameTag=function(){
  var r=_nt.apply(this,arguments);
  try{var t=T();if(!t)return r;var im=IMG[IT[t.i].k];if(!im||!im.complete||!im.naturalWidth)return r;
    var og=GY;try{if(window.TAGUP&&TAGUP.CF&&TAGUP.CF.enable)GY=og-TAGUP.up()*s;
      var X=(P.x-cam)*s,fs=Math.max(10,12*s),bh=Math.max(2.5,3*s),mh=Math.max(2,2.25*s),yM=GY-80*s-mh,yH=yM-bh-2,yN=yH-4;
      g.save();g.font='bold '+fs+'px KTH Serif,Songti SC,STKaiti,KaiTi,serif';
      var tx=(window.NHX?NHX.icMe():'')+CN(cur)+' · ',rn=ZC.rn(),ck=fs+'|'+tx+rn;if(ck!==wcK){wcK=ck;wcA=g.measureText(tx).width;wcB=g.measureText(rn).width}var wa=wcA,wb=wcB;g.restore();
      var H=Math.max(16,fs*1.7),x1=X+(wa+wb)/2+3;
      g.save();g.globalAlpha=1;g.drawImage(im,x1,yN-fs*.4-H/2,H,H);g.restore()
    }finally{GY=og}}catch(e){}
  return r}}

/* ---------- ô trong Túi ---------- */
function inject(){
  var col=document.querySelector('#bag .eqd .chp .tsm-l');if(!col||col.querySelector('.tkq-s'))return;
  var t=T(),it=t?IT[t.i]:null;
  col.insertAdjacentHTML('beforeend','<div class="tsm-s tkq-s '+(t?'on':'lk')+'" style="--tc:'+(it?it.c:'#b8964e')+'" onclick="TKQ.open()" title="Thánh khí">'
    +'<img src="'+IC[it?it.k:'kiem']+'" alt="">'+(t?'<i>'+t.lv+'</i>':'<i>＋</i>')+'</div>')}
function refreshSlot(){try{var c=document.querySelector('#bag .eqd .chp .tkq-s');if(c)c.remove();inject()}catch(e){}}
var _ui=window.ui;window.ui=function(){var a=_ui.apply(this,arguments);try{inject()}catch(e){console.warn('TKQ',e)}return a};

/* ---------- bảng chọn / nâng cấp ---------- */
function online(){try{return !!(window.KCL&&KCL.OK&&KCL.sess&&KCL.sess()&&KCL.rpc)}catch(e){return false}}
function rpc(fn,args){return new Promise(function(res){try{if(!online())return res({status:'login'});
  KCL.rpc(fn,args||{}).then(function(r){res(r&&typeof r==='object'?r:{status:'net'})}).catch(function(e){res({status:(e&&e.status===404)?'nosql':'net'})})}catch(e){res({status:'net'})}})}
var ME=null,sel=-1,msg='',busy=false,conf=-1;
function KK(i){return ME&&ME.status==='ok'&&ME.k?(ME.k[i]|0):0}
function errTx(r){var s=r&&r.status;return s==='login'||s==='auth'?'☁ Cần đăng nhập tài khoản':s==='nosql'?'⚠ Máy chủ chưa có hàm tk_use (cần chạy thanh_khi_v2.sql)':s==='poor'?'Bạn không còn món này (chế ở Nhà Tinh Luyện)':'Lỗi mạng, thử lại'}
function descBase(){return '+'+CF.base+'% sát thương · +'+CF.base+'% giáp · +'+CF.base+'% máu · +'+CF.base+'% xuyên giáp (cố định)'}
/* phí nâng từ cấp lv → lv+1; tổng phí nâng n cấp liên tiếp */
function cost1(lv){return CF.cost+CF.costStep*(lv-1)}
function costN(lv,n){var c=0;for(var j=0;j<n;j++)c+=cost1(lv+j);return c}
function nUp(t){var n=0,g=G();while(t.lv+n<CF.maxLv&&g>=cost1(t.lv+n)){g-=cost1(t.lv+n);n++}return n}
function descOwn(i,lv){
  if(i===0)return 'Sát thương thần thông +'+(CF.kiem+ex(lv))+'%';
  if(i===1)return 'Sát thương bạo kích +'+(CF.cung+ex(lv))+'%';
  if(i===2)return 'Miễn thương +'+CF.khien+'% · '+ign(lv)+'% bỏ qua 1 đòn mạnh của quái (≥2% máu tối đa)';
  return 'Sát thương kỹ năng +'+(CF.gay+ex(lv))+'%'}
function guard(el){['pointerdown','touchstart','keydown','keyup'].forEach(function(t){el.addEventListener(t,function(e){e.stopPropagation()})})}
function close(){var o=document.getElementById('tkq-ov');if(o)o.remove()}
function btn(k,t,on,bg){return '<button data-tkq="'+k+'" '+(on?'':'disabled')+' style="width:100%;margin-top:8px;padding:10px;border-radius:8px;border:1px solid #b8964e;color:#fff;font-weight:bold;background:'+(bg||'#7a4a18')+';'+(on?'':'opacity:.45')+'">'+t+'</button>'}
function render(){
  var o=document.getElementById('tkq-ov');if(!o)return;
  var t=T(),h='<h3>✨ Thánh Khí</h3><small>'+(t?'Nhân vật đã chọn <b>'+IT[t.i].n+'</b> — không thể đổi.':'Mỗi nhân vật chỉ chọn 1 món để tinh luyện, không thể đổi. Thánh Khí chế ở 🏠 Nhà Tinh Luyện (Làng Tân Thủ 3 · Nhà Số 5).')+'</small>';
  h+='<div class="tsm-g">';
  IT.forEach(function(it,i){
    var mine=t&&t.i===i,lock=t&&!mine,pick=!t&&sel===i;
    h+='<div class="tsm-it '+(mine||pick?'on':'')+'" data-tkq="c'+i+'" style="--tc:'+it.c+';'+(lock?'opacity:.4;filter:grayscale(.7);':'')+'cursor:pointer">'
      +'<div class="ic"><img src="'+IC[it.k]+'" style="width:56px;height:56px"></div><b>'+it.n+'</b>'
      +'<em style="opacity:.9">'+it.r+'</em>'
      +'<em>'+(mine?'Cấp '+t.lv+'/'+CF.maxLv:lock?'🔒':'Đang có: ×'+(ME&&ME.status==='ok'?KK(i):'…'))+'</em></div>'});
  h+='</div>';
  var i=t?t.i:sel;
  if(i>=0){
    var it=IT[i],lv=t?t.lv:1;
    h+='<div class="tsm-it on" style="--tc:'+it.c+';text-align:left;min-height:0"><b style="color:'+it.c+'">'+it.n+(t?' — Cấp '+lv+'/'+CF.maxLv:' (cấp 1 khi chọn)')+'</b>'
      +'<em style="opacity:.9">'+descBase()+'</em><em style="opacity:.9">'+descOwn(i,lv)+'</em>';
    if(t&&lv<CF.maxLv)h+='<em style="opacity:.9">Cấp '+(lv+1)+': '+descOwn(i,lv+1)+'</em>';
    var s=CF.sk[i],un=t&&lv>=CF.maxLv;
    h+='<em style="opacity:.95;margin-top:6px;color:'+(un?'#9dffa0':'#d8c8a0')+'">'+(un?'✅':'🔒')+' Thần thông thánh khí · <b>'+s.n+'</b><br>'+s.d+(un?'':' <br>(mở khi đạt cấp '+CF.maxLv+')')+'</em></div>';
    if(!t){var k=KK(i),cf=conf===i;
      h+=btn('pick'+i,cf?'⚠ Bấm lần nữa để XÁC NHẬN (không thể đổi, tiêu hao 1 món)':'✨ Chọn tinh luyện (đang có ×'+k+')',!busy&&k>0,cf?'#9a2a1a':null);
      if(ME&&ME.status==='ok'&&k<1)h+='<small style="margin-top:6px">Bạn chưa có món này — dung hợp ở Nhà Tinh Luyện (Làng Tân Thủ 3 · Nhà Số 5).</small>'}
    else if(lv<CF.maxLv){
      h+=btn('up','⬆ Nâng cấp '+lv+' → '+(lv+1)+' · '+nf(cost1(lv))+' 💰',!busy&&G()>=cost1(lv));
      var nu=nUp(t);if(nu>1)h+=btn('upmax','⏫ Nâng nhanh ×'+nu+' cấp → '+(lv+nu)+' · '+nf(costN(lv,nu))+' 💰',!busy,'#5a3a14')}
    else h+='<small style="margin-top:8px;color:#9dffa0">Đã đạt cấp tối đa.</small>'}
  if(msg)h+='<div style="margin-top:8px;font-size:12px;color:#ffd76a">'+msg+'</div>';
  h+=btn('x','Đóng',true,'#3a2a20');
  o.querySelector('.tsm-bx').innerHTML=h}
function open(){
  close();var o=document.createElement('div');o.id='tkq-ov';o.className='tsm-ov';
  o.innerHTML='<div class="tsm-bx" style="--tc:#ffd27a;max-height:92vh;overflow:auto"></div>';
  guard(o);document.body.appendChild(o);msg='';sel=-1;conf=-1;
  o.addEventListener('click',function(ev){
    if(ev.target===o){close();return}
    var b=ev.target.closest('[data-tkq]');if(!b||b.disabled)return;var k=b.getAttribute('data-tkq');
    if(k==='x'){close();return}
    if(k.charAt(0)==='c'){if(!T()){sel=+k.slice(1);msg='';conf=-1}render();return}
    if(k==='up')return up(1);
    if(k==='upmax')return up(99);
    if(k.slice(0,4)==='pick')return pick(+k.slice(4))});
  render();
  rpc('tk_me').then(function(m){if(m&&m.status==='ok')ME=m;else if(m&&m.status!=='ok'&&!ME){ME=m;msg=errTx(m)}render()})}
function up(n){
  var t=T();if(!t||t.lv>=CF.maxLv||busy)return;
  n=Math.min(n,nUp(t));
  if(n<1){msg='Không đủ vàng ('+nf(cost1(t.lv))+' 💰)';render();return}
  gold-=costN(t.lv,n);PS[cur].tkq={i:t.i,lv:t.lv+n};sav();msg='';
  say('✨ '+IT[t.i].n+' lên cấp '+(t.lv+n)+'!',IT[t.i].c);
  if(t.lv+n>=CF.maxLv)say('🌟 Mở thần thông: '+CF.sk[t.i].n,'#9dffa0');
  refreshSlot();render()}
function pick(i){
  if(T()||busy||i<0||i>3)return;
  if(conf!==i){conf=i;msg='';render();return}
  var who=cur,pp=PS[cur];
  busy=true;conf=-1;msg='Đang xác nhận với máy chủ…';render();
  rpc('tk_use',{p_kind:i+1}).then(function(r){
    busy=false;
    if(r&&r.status==='ok'){
      /* ghi vào ĐÚNG nhân vật đã bấm, kể cả khi đã đổi nhân vật trong lúc chờ máy chủ */
      if(!(pp.tkq&&pp.tkq.i>=0)){pp.tkq={i:i,lv:1};sav()}
      if(r.k)ME={status:'ok',k:r.k,p:(ME&&ME.p)||[0,0,0,0]};
      msg='';sel=-1;
      if(cur===who){say('✨ Chế tạo thành công '+IT[i].n+' · Cấp 1','#ffd76a');refreshSlot()}}
    else msg=errTx(r);
    render()})}

window.TKQ={cfg:CF,open:open,close:close,get:T,items:IT};
})();
